// Projection value index — record JAH-GPC-PROJECTOR-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"lumens": 2000, "contrast_k": 10, "price_usd": 400};
var value = (m.lumens*m.contrast_k/m.price_usd);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-PROJECTOR-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-PROJECTOR-000001|' + value.toFixed(2) + ' projection index');

